def sorted_preview(values, reducer):
    reduced = reducer.reduce(values.copy())
    preview = reduced.copy()
    preview.sort()
    return preview
class IdentityReducer:
    def reduce(self, values):
        return values


class DoubleReducer:
    def reduce(self, values):
        return [value * 2 for value in values]
